export const LEVEL_METER_RELEASE_DB_PER_SECOND = 24;
export const LEVEL_METER_PEAK_HOLD_MS = 1000;

export type LevelMeterRange = { minDb: number; maxDb: number };

export type LevelMeterReading = { levelDb: number; peakDb: number; peakHeldUntilMs: number };

export function clampLevelDb(levelDb: number, { minDb, maxDb }: LevelMeterRange) {
  if (Number.isNaN(levelDb)) return minDb;
  return Math.min(maxDb, Math.max(minDb, levelDb));
}

export function levelMeterFraction(levelDb: number, scale: LevelMeterRange) {
  const span = scale.maxDb - scale.minDb;
  if (!(span > 0)) return 0;
  return (clampLevelDb(levelDb, scale) - scale.minDb) / span;
}

export function advanceLevelMeterReading(
  reading: LevelMeterReading,
  targetDb: number,
  elapsedMs: number,
  nowMs: number,
  scale: LevelMeterRange,
): LevelMeterReading {
  const target = clampLevelDb(targetDb, scale);
  const fallDb = (LEVEL_METER_RELEASE_DB_PER_SECOND * Math.max(0, elapsedMs)) / 1000;
  const levelDb = Math.max(target, reading.levelDb - fallDb);
  if (levelDb >= reading.peakDb) return { levelDb, peakDb: levelDb, peakHeldUntilMs: nowMs + LEVEL_METER_PEAK_HOLD_MS };
  const peakDb = nowMs < reading.peakHeldUntilMs ? reading.peakDb : Math.max(levelDb, reading.peakDb - fallDb);
  return { levelDb, peakDb, peakHeldUntilMs: reading.peakHeldUntilMs };
}

export function levelMeterReadingSettled(reading: LevelMeterReading, targetDb: number, scale: LevelMeterRange) {
  return reading.levelDb === clampLevelDb(targetDb, scale) && reading.peakDb === reading.levelDb;
}

@layer components {
  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="root"]) {
    --cui-range-level-warning-background: var(--warning);
    --cui-range-level-clip-background: var(--destructive);
    --cui-range-level-muted-background: var(--muted-foreground);
    --cui-range-level-size: calc(var(--spacing) * 2);
    --cui-range-level-scale-foreground: var(--muted-foreground);
    --_range-level-peak-size: 2px;
    --_range-level-zone-angle: 90deg;
    gap: var(--spacing);
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="root"][data-orientation="horizontal"]) {
    grid-template-rows: var(--cui-range-level-size);
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="root"][data-orientation="horizontal"]:dir(rtl)) {
    --_range-level-zone-angle: 270deg;
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="root"][data-orientation="vertical"]) {
    --_range-level-zone-angle: 0deg;
    grid-auto-flow: column;
    grid-template-columns: var(--cui-range-level-size);
    grid-template-rows: minmax(0, 1fr);
    inline-size: max-content;
    min-block-size: calc(var(--spacing) * 16);
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="track"]) {
    border-radius: var(--cui-range-track-radius);
    background: var(--cui-range-track-background);
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="scale"]) {
    block-size: calc(1lh + var(--spacing));
    color: var(--cui-range-level-scale-foreground);
  }

  :where(
    [data-range-kind="level-meter"][data-slot="root"][data-orientation="vertical"]
      [data-control-family="range"][data-range-kind="level-meter"][data-slot="scale"]
  ) {
    block-size: auto;
    inline-size: calc(var(--spacing) * 8);
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="tick"]) {
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: calc(var(--_range-level-tick) * 100%);
    display: flex;
    flex-direction: column;
    align-items: center;
    translate: -50% 0;
    white-space: nowrap;
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="tick"]:dir(rtl)) {
    translate: 50% 0;
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="tick"])::before {
    content: "";
    inline-size: 1px;
    block-size: var(--spacing);
    background: currentColor;
    opacity: 0.5;
  }

  :where(
    [data-range-kind="level-meter"][data-slot="root"][data-orientation="vertical"]
      [data-control-family="range"][data-range-kind="level-meter"][data-slot="tick"]
  ) {
    inset-block: auto calc(var(--_range-level-tick) * 100%);
    inset-inline-start: 0;
    flex-direction: row;
    gap: calc(var(--spacing) * 1.5);
    translate: 0 50%;
  }

  :where(
    [data-range-kind="level-meter"][data-slot="root"][data-orientation="vertical"]
      [data-control-family="range"][data-range-kind="level-meter"][data-slot="tick"]
  )::before {
    inline-size: var(--spacing);
    block-size: 1px;
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="bar"]),
  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="peak"]) {
    background-image: linear-gradient(
      var(--_range-level-zone-angle),
      var(--cui-range-indicator-background) calc(var(--_range-level-warning-start, 1) * 100%),
      var(--cui-range-level-warning-background) 0 calc(var(--_range-level-clip-start, 1) * 100%),
      var(--cui-range-level-clip-background) 0
    );
  }

  :where(
    [data-range-kind="level-meter"][data-slot="root"][data-muted]
      [data-control-family="range"][data-range-kind="level-meter"]:is([data-slot="bar"], [data-slot="peak"])
  ) {
    background: var(--cui-range-level-muted-background);
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="bar"]) {
    clip-path: inset(0 calc((1 - var(--_range-level, 0)) * 100%) 0 0 round var(--cui-range-indicator-radius));
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="peak"]) {
    clip-path: inset(
      0 calc((1 - var(--_range-level-peak, 0)) * 100%) 0 calc(var(--_range-level-peak, 0) * 100% - var(--_range-level-peak-size))
    );
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="bar"]:dir(rtl)) {
    clip-path: inset(0 0 0 calc((1 - var(--_range-level, 0)) * 100%) round var(--cui-range-indicator-radius));
  }

  :where([data-control-family="range"][data-range-kind="level-meter"][data-slot="peak"]:dir(rtl)) {
    clip-path: inset(
      0 calc(var(--_range-level-peak, 0) * 100% - var(--_range-level-peak-size)) 0 calc((1 - var(--_range-level-peak, 0)) * 100%)
    );
  }

  :where(
    [data-range-kind="level-meter"][data-slot="root"][data-orientation="vertical"]
      [data-control-family="range"][data-range-kind="level-meter"][data-slot="bar"]
  ) {
    clip-path: inset(calc((1 - var(--_range-level, 0)) * 100%) 0 0 0 round var(--cui-range-indicator-radius));
  }

  :where(
    [data-range-kind="level-meter"][data-slot="root"][data-orientation="vertical"]
      [data-control-family="range"][data-range-kind="level-meter"][data-slot="peak"]
  ) {
    clip-path: inset(
      calc((1 - var(--_range-level-peak, 0)) * 100%) 0 calc(var(--_range-level-peak, 0) * 100% - var(--_range-level-peak-size)) 0
    );
  }
}

